diff --git a/jwt/api_jwt.py b/jwt/api_jwt.py
index 051ed34..9fae8d8 100644
--- a/jwt/api_jwt.py
+++ b/jwt/api_jwt.py
@@ -475,7 +475,7 @@ class PyJWT:
     ) -> None:
         try:
             iat = int(payload["iat"])
-        except ValueError:
+        except (ValueError, TypeError, OverflowError):
             raise InvalidIssuedAtError(
                 "Issued At claim (iat) must be an integer."
             ) from None
@@ -490,7 +490,7 @@ class PyJWT:
     ) -> None:
         try:
             nbf = int(payload["nbf"])
-        except ValueError:
+        except (ValueError, TypeError, OverflowError):
             raise DecodeError("Not Before claim (nbf) must be an integer.") from None

         if nbf > (now + leeway):
@@ -504,7 +504,7 @@ class PyJWT:
     ) -> None:
         try:
             exp = int(payload["exp"])
-        except ValueError:
+        except (ValueError, TypeError, OverflowError):
             raise DecodeError(
                 "Expiration Time claim (exp) must be an integer."
             ) from None

diff --git a/pydantic_settings/sources/providers/cli.py b/pydantic_settings/sources/providers/cli.py
index fd334ac..d8ae649 100644
--- a/pydantic_settings/sources/providers/cli.py
+++ b/pydantic_settings/sources/providers/cli.py
@@ -205,7 +205,7 @@ class _CliArg(BaseModel):

     def subcommand_alias(self, sub_model: type[BaseModel]) -> str:
         return self.get_kebab_case(
-            sub_model.__name__ if len(self.sub_models) > 1 else self.preferred_alias, self.kebab_case
+            sub_model.__name__ if len(self.sub_models) > 1 else self.case_sensitive_alias, self.kebab_case
         )

     @cached_property
@@ -272,6 +272,11 @@ class _CliArg(BaseModel):
     def preferred_alias(self) -> str:
         return self._alias_names[0]

+    @cached_property
+    def case_sensitive_alias(self) -> str:
+        # Subcommands are always case sensitive, so use the declared alias rather than the lowercased one.
+        return _get_alias_names(self.field_name, self.field_info)[0][0]
+
     @cached_property
     def is_alias_path_only(self) -> bool:
         return self._is_alias_path_only
